/* 
  How Basic Auth works under the hood 
*/

// 1. You have credentials:
const username = "admin";
const password = "supersecret";

// 2. You combine them with a colon:
const combined = "admin:supersecret";

// 3. You Base64 encode the string:
// (In JS, btoa() does this)
const encoded = btoa(combined); // Yields: "YWRtaW46c3VwZXJzZWNyZXQ="

// 4. You attach it to the HTTP Request Header:
fetch('https://api.com/data', {
  headers: {
    'Authorization': `Basic YWRtaW46c3VwZXJzZWNyZXQ=`
  }
});
